  res.cookies.set('access_token', '', { ...ACCESS_COOKIE_OPTIONS, maxAge: 0 });
  res.cookies.set('refresh_token', '', { ...REFRESH_COOKIE_OPTIONS, maxAge: 0 });
  return res;
}

