  const oldRefreshToken = cookieStore.get('refresh_token')?.value;

  if (!oldRefreshToken) {
    return NextResponse.json({ error: 'No refresh token' }, { status: 401 });
  }

  const result = await rotateRefreshToken(oldRefreshToken);
  if (!result) {
