  folderId: mongoose.Types.ObjectId;
  tokenHash: string;
  role: "viewer" | "editor";
  passwordHash: string | null;
  expiresAt: Date;
  revokedAt: Date | null;
  createdBy: mongoose.Types.ObjectId;
  maxUses: number | null;
  useCount: number;
  lastAccessedAt: Date | null;
  failedPasswordAttempts: number;
  lockedUntil: Date | null;
  createdAt: Date;
  updatedAt: Date;
}

