      storageUrl: key,
      destination: key,
      uploadId: UploadId,
      folders_id: folderId ?? null,
      folderId: folderId ?? null,
      status: "pending",
    });
  }

  const totalParts = Math.ceil(size / CHUNK_SIZE);

  return NextResponse.json(
