      { status: 400 }
    );
  }

  // Generate one presigned URL per part (15 min expiry each)
  const urls = await Promise.all(
    partNumbers.map((partNumber) =>
      getSignedUrl(
        s3,
        new UploadPartCommand({
          Bucket: BUCKET,
          Key: key,
          UploadId: uploadId,
          PartNumber: partNumber,
        }),
        { expiresIn: 900 }
      )
    )
  );

  return NextResponse.json({ urls }, { status: 200 });
}

