    name: name.trim(),
    owner_id: String(parent.owner_id),
    owner_email: owner?.email ?? parent.owner_email,
    parent_id: access.folderId,
    ancestors: [...parent.ancestors, parent._id],
    depth: parent.depth + 1,
  });

  return folder;
}

