ShareLinkSchema.index({ folderId: 1, revokedAt: 1 });

const ShareLink: Model<IShareLink> =
  mongoose.models.ShareLink ||
  mongoose.model<IShareLink>("ShareLink", ShareLinkSchema);

export default ShareLink;
