    _id: id,
    owner_id: user.userId,
    status: "uploaded",
    deleted: { $ne: true },
  }).lean();

  if (!file) {
    return NextResponse.json({ error: "File not found" }, { status: 404 });
  }

  const versions = await FileVersion.find({ file_id: id }).sort({ version: -1 }).lean();

  return NextResponse.json({
    file: {
