      version.size,
      version.mimetype,
      file.filename,
      "attachment",
      encryptionKey?.keyBase64,
    );
  }

  const url = await createS3DownloadUrl(
    version.storageUrl,
    file.filename,
    version.mimetype,
  );
  return Response.redirect(url, 302);
}
