        folderId: folderId ?? null,
        folders_id: folderId ?? null,
        backend: "telegram",
        totalChunks,
        chunkSize: CHUNK_SIZE,
        status: "pending",
        encryptionIv: encryptionSalt,
      });
    } else if (useEncryption) {
