    filename: string;
    mimeType: string;
    size: number;
    folderId: string | null;
    hash: string;
    fileId?: string;
  };

  if (!filename || !mimeType || !size || !hash) {
    return NextResponse.json(
      { error: "filename, mimeType, size, and hash are required" },
      { status: 400 }
    );
  }

