export async function createFolder(userId: string, userEmail: string, name: string, parentId?: string | null) {
  if (!name?.trim()) throw new ServiceError("Folder name required", 400);
  await connectDB();

  if (!parentId) {
    return Folder.create({
      name: name.trim(),
      owner_id: userId,
      owner_email: userEmail,
      parent_id: null,
      ancestors: [],
      depth: 0,
      createdBy: userId,
