        { folderId, principalType: "user", principalId: actorId },
        { $set: { role: "editor", state: "active", grantedBy: newOwner._id } },
        { upsert: true, session }
      );

      result = { folderCount: ids.length, newOwnerId: String(newOwner._id) };
