  const totalChunks = chunks.length;

  const encryptionKey = file.encryptionKey
    ? Buffer.from(file.encryptionKey, "base64")
    : null;

  const encryptionKeyDoc = await EncryptionKeyModel.findOne({ fileId }).lean();
