        const buffer = Buffer.from(await res.arrayBuffer());
        after(() => cacheChunkBestEffort(versionId, index, buffer));
        return buffer;
      })(),
    );
  }

  for (let i = 0; i < Math.min(PREFETCH, totalChunks); i++) startFetch(i);

  let idx = 0;

  const stream = new ReadableStream({
    async pull(controller: ReadableStreamDefaultController) {
      if (idx >= totalChunks) { controller.close(); return; }
      startFetch(idx + PREFETCH);
      try {
        const data = await fetchQueue.get(idx)!;
        fetchQueue.delete(idx);

        // Backward compat: decrypt if server-side encryptionKey is present (old method)
        let output: Buffer;
        if (encryptionKey) {
          const nonce = chunks[idx].nonce ? parseNonce(chunks[idx].nonce) : null;
          if (nonce && nonce.length > 0) {
            output = decryptChunk(data, nonce, encryptionKey);
          } else {
            output = data;
          }
        } else {
          // New zero-knowledge mode: stream encrypted data as-is for client to decrypt
          output = data;
        }

        controller.enqueue(new Uint8Array(output.buffer, output.byteOffset, output.byteLength));
        idx++;
      } catch (err) {
        controller.error(err as Error);
      }
    },
  });

  return new Response(stream, {
    status: 200,
    headers: {
      "Content-Type": mimetype || "application/octet-stream",
      // filename is the user-supplied original upload name — a raw quote in
      // it breaks out of the quoted filename="..." parameter. Percent-encode
      // it, matching createS3DownloadUrl/createS3PresignedUrl above.
      "Content-Disposition": `${disposition}; filename="${encodeURIComponent(filename)}"`,
      "Content-Length": totalSize.toString(),
      // Content per version is immutable once uploaded, so it's safe to cache
      // hard. `private` (not `public`) since this is an authenticated,
      // per-user stream — only the requesting browser should cache it, not
      // shared proxies/CDNs. Matches the 24h TTL used for S3-backed files.
      "Cache-Control": "private, max-age=86400, immutable",
    },
  });
}

export async function createVersionDownloadResponse(
  fileId: string,
  versionId?: string,
) {
  const file = await File.findById(fileId).lean();
  if (!file) return new Response("File not found", { status: 404 });

  const version = versionId
    ? await FileVersionModel.findById(versionId).lean()
    : file.currentVersionId
      ? await FileVersionModel.findById(file.currentVersionId).lean()
      : null;

  if (!version) return new Response("Version not found", { status: 404 });

  if (version.backend === "telegram") {
    // Backward compat: look for server-side key for old files
    const encryptionKey = file.encryptionKey
      ? await EncryptionKeyModel.findOne({ fileId }).lean()
      : null;
    return createTelegramDownloadStream(
      version._id.toString(),
      version.size,
      version.mimetype,
      file.filename,
      "attachment",
      encryptionKey?.keyBase64,
    );
  }

  const url = await createS3DownloadUrl(
    version.storageUrl,
    file.filename,
    version.mimetype,
  );
  return Response.redirect(url, 302);
