            controller.error(new Error(`Chunk ${idx} integrity check failed`));
            return;
          }
        }

        controller.enqueue(new Uint8Array(decrypted.buffer, decrypted.byteOffset, decrypted.byteLength));
        idx++;
      } catch (err) {
        controller.error(err as Error);
      }
    },
  });

