  await connectDB();
  await requireFolderRole(userId, folderId, "editor");

  const folder = await Folder.findOne({ _id: folderId, deleted: { $ne: true } }).lean();
  if (!folder) throw new ServiceError("Folder not found", 404);

  const deletedAt = new Date();
