) {
  await connectDB();

  const file = await File.findOne({
    hash,
    owner_id: userId,
    status: "uploaded",
    backend,
  }).lean();

  return file;
}

import { getAuthUser } from "@/server/auth/auth";
import { NextRequest, NextResponse } from "next/server";
import { moveFile, deleteFile, renameFile } from "@/server/services/fileService";
