        owner_id: owner._id,
        owner_email: owner.email,
        storageUrl: `telegram/${owner._id}/${Date.now()}-${filename}`,
        folderId: folderId ?? null,
        folders_id: folderId ?? null,
        backend: "telegram",
        totalChunks,
        chunkSize: CHUNK_SIZE,
        status: "pending",
