      type?: "link" | "user";
      role?: FolderRole;
      expiresInDays?: number;
      password?: string;
      maxUses?: number;
      email?: string;
      userId?: string;
    };

    const idempotencyKey = req.headers.get("Idempotency-Key");

    try {
      if (body.type === "user") {
