  if (!text) return "";
  const index = text.toLowerCase().indexOf(query.toLowerCase());
  if (index < 0) return text.slice(0, 140);
  const start = Math.max(0, index - 60);
  return `${start > 0 ? "..." : ""}${text.slice(start, index + query.length + 90)}`;
}
