          { fileId: file._id },
          { $set: { versionId: result.versionId } }
        ).session(session);
      }
    });

    return NextResponse.json({ file: result!.file, versionId: result!.versionId, version: result!.version, versioned: result!.versioned });
  } finally {
    await session.endSession();
  }
}
