    if (!folder) return NextResponse.json({ error: "Nothing to update" }, { status: 400 });
    return NextResponse.json({ folder });
  } catch (err) {
    if (err instanceof ServiceError) return NextResponse.json({ error: err.message }, { status: err.status });
