  await TelegramChunk.deleteMany({ fileId: id }).catch((err) => {
    console.error(`[POST /api/files/${id}/fallback-to-s3] failed to delete TelegramChunk records`, err);
    cleanupWarnings.push("Failed to delete TelegramChunk records");
