  await File.findByIdAndUpdate(id, {
    $set: {
      backend: "s3",
      status: "s3_pending",
      storageUrl: key,
      destination: key,
      lastError: null,
      fallbackCompletedAt: new Date(),
      // The S3 upload path never had a decrypt mechanism (no manifest/
