    filename,
    owner_id: ownerId,
    folderId,
    status: "uploaded",
    hash: { $ne: hash },
    deleted: { $ne: true },
    ...(excludeFileId ? { _id: { $ne: excludeFileId } } : {}),
  }).session(session);
