  }

  const { id } = await params;
  if (!ObjectId.isValid(id)) {
    return NextResponse.json({ error: "Invalid file id" }, { status: 400 });
  }

  await connectDB();

  const file = await File.findOne({
    _id: id,
    owner_id: user.userId,
    status: "uploaded",
    deleted: { $ne: true },
  }).lean();

  if (!file) {
