    await connectDB();

    const statusParam = req.nextUrl.searchParams.get("status") || "uploaded";
    const statuses = statusParam.split(",").map((s) => s.trim()).filter(Boolean);
    const limitParam = req.nextUrl.searchParams.get("limit");
