        console.warn(`[POST /api/files/telegram/chunk] rate-limited on file ${fileId} chunk ${chunkIndex}, retrying in ${delay}ms (attempt ${attempt + 1}/${MAX_RETRIES}, retry_after=${err?.retryAfterSeconds ?? "n/a"})`);
