    hash: file.hash,
    owner_id: user._id,
    status: "uploaded",
    deleted: { $ne: true },
  });
  if (existingUpload) {
    console.warn(`[POST /api/files/${id}/fallback-to-s3] aborted: duplicate of already-uploaded file ${existingUpload._id}`);
    return NextResponse.json(
      { error: "Duplicate file", existingFile: existingUpload },
      { status: 409 },
    );
