    filename: string;
    mimeType: string;
    size: number;
    hash: string;
    folderId: string | null;
    fileId?: string;
    encryptionSalt?: string;
    useEncryption?: boolean;
    useDek?: boolean;
  };

  if (!filename || !size || !hash) {
    return NextResponse.json(
      { error: "filename, size, and hash are required" },
      { status: 400 }
    );
