      _id: fileId,
      status: { $in: ["pending", "uploading", "paused"] },
      backend: "telegram",
      deleted: { $ne: true },
    });

    if (!file || !(await canUploadToFile(user._id.toString(), file))) {
      return NextResponse.json(
        { error: "Upload not found or not in valid state" },
        { status: 404 }
