    return Folder.create({
      name: name.trim(),
      owner_id: userId,
      owner_email: userEmail,
      parent_id: null,
      ancestors: [],
      depth: 0,
      createdBy: userId,
    });
  }

  if (!ObjectId.isValid(parentId)) throw new ServiceError("Invalid parentId", 400);

  const parent = await Folder.findOne({ _id: parentId, deleted: { $ne: true } }).lean();
