    } catch (err) {
      console.error(`[POST /api/files/${id}/fallback-to-s3] failed to delete Telegram message ${chunk.telegramMessageId}`, err);
      cleanupWarnings.push(`Failed to delete Telegram message ${chunk.telegramMessageId}`);
