  if (Date.now() / 1000 - authDate > 86400) {
    throw new Error('Telegram auth expired');
  }

  try {
    await connectDB();
  } catch {
    throw new Error('Database error');
  }

  const telegramId = payload.id;
  let user = await User.findOne({ provider: 'telegram', providerId: telegramId });

