      Bucket: BUCKET,
      Key: storageUrl,
      ResponseContentDisposition: `inline; filename="${encodeURIComponent(file.filename)}"`,
      ResponseContentType: file.mimetype,
    }),
    { expiresIn: 60 * 10 }
  );

  return NextResponse.json({ url });
}
