      return NextResponse.json(
        { error: "Storage limit exceeded" },
        { status: 413 }
      );
    }

    let existingFileRecord = null;

    if (fileId) {
      existingFileRecord = await File.findOne({
        _id: fileId,
        owner_id: user._id,
        status: "s3_pending",
        backend: "s3",
        deleted: { $ne: true },
      });
      if (!existingFileRecord) {
