        `total=${tDone - tStart}ms accessChecks=${tAfterAccessChecks - tStart}ms ` +
        `readAndEncrypt=${tAfterEncryption - tAfterAccessChecks}ms sendDocument=${tSendDone - tSendStart}ms ` +
        `dbWrite=${tDone - tSendDone}ms`
