      _id: id,
      owner_id: user._id,
      backend: "telegram",
      status: { $in: ["pending", "uploading", "paused", "fallback_cleanup"] },
    },
    {
      $set: {
        status: "fallback_cleanup",
        fallbackFrom: "telegram",
        fallbackReason: reason ?? "telegram_failed_after_retries",
        fallbackStartedAt: new Date(),
