      type: Schema.Types.ObjectId,
      ref: 'User',
      required: [true, 'sharedwith user is required'],
    },
    permission: {
      type: String,
      enum: ['read', 'write', 'admin'],
      required: [true, 'Permission level is required'],
    },
    resource_id: {
      type: Schema.Types.ObjectId,
      required: [true, 'Resource ID is required'],
    },
    resource_type: {
      type: String,
      enum: ['file', 'folder'],
