  const { fileId, encryptionIv, encryptionKey } = body as {
    fileId: string;
    encryptionIv?: string;
    encryptionKey?: string;
  };

  if (!fileId) {
    return NextResponse.json({ error: "fileId is required" }, { status: 400 });
  }

  await connectDB();

