export class DecryptingDuplex extends Duplex {
  private key: Buffer;
  private inputNonce: Buffer | null = null;
  private pendingBuffers: Buffer[] = [];

  constructor(key: Buffer) {
    super({ objectMode: true });
    this.key = key;
  }

  _read(size: number): void {
    this.processPending();
  }

  _write(chunk: Buffer, encoding: BufferEncoding, callback: (error?: Error | null) => void): void {
    try {
      if (chunk.length < AUTH_TAG_SIZE) {
        callback(new Error("Chunk too short for auth tag"));
        return;
      }
      const authTag = chunk.subarray(chunk.length - AUTH_TAG_SIZE);
      const ciphertext = chunk.subarray(0, chunk.length - AUTH_TAG_SIZE);
      const decipher = crypto.createDecipheriv(ALGORITHM, this.key, this.inputNonce as Buffer);
      decipher.setAuthTag(authTag);
      const decrypted = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
      this.push(decrypted);
      callback();
    } catch (err) {
      callback(err as Error);
    }
  }

  _final(callback: (error?: Error | null) => void): void {
    callback();
  }

  _destroy(error: Error | null, callback: (error: Error | null) => void): void {
    callback(error);
  }

  setNonce(nonce: Buffer): void {
    this.inputNonce = nonce;
  }

  private processPending(): void {
    while (this.pendingBuffers.length > 0) {
      const buffer = this.pendingBuffers.shift();
      if (buffer && this.inputNonce) {
        try {
          if (buffer.length < AUTH_TAG_SIZE) {
            this.emit("error", new Error("Chunk too short for auth tag"));
            continue;
          }
          const authTag = buffer.subarray(buffer.length - AUTH_TAG_SIZE);
          const ciphertext = buffer.subarray(0, buffer.length - AUTH_TAG_SIZE);
          const decipher = crypto.createDecipheriv(ALGORITHM, this.key, this.inputNonce);
          decipher.setAuthTag(authTag);
          const decrypted = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
          this.push(decrypted);
        } catch (err) {
          this.emit("error", err as Error);
        }
      }
    }
  }
}

import crypto from "crypto";
import { Transform, Readable } from "stream";

const ALGORITHM = "aes-256-gcm";
const NONCE_SIZE = 12;
const AUTH_TAG_SIZE = 16;

export interface EncryptionResult {
  encrypted: Buffer;
  nonce: Buffer;
  authTag: Buffer;
}

export function generateKey(): Buffer {
  return crypto.randomBytes(32);
}

export function generateNonce(): Buffer {
  return crypto.randomBytes(NONCE_SIZE);
}

export function encryptChunk(plaintext: Buffer, key: Buffer): EncryptionResult {
  const nonce = generateNonce();
  const cipher = crypto.createCipheriv(ALGORITHM, key, nonce);
  const encrypted = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const authTag = cipher.getAuthTag();
  return { encrypted, nonce, authTag };
}

export function encryptChunkWithNonce(plaintext: Buffer, nonce: Buffer, key: Buffer): Buffer {
  const cipher = crypto.createCipheriv(ALGORITHM, key, nonce);
  const encrypted = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const authTag = cipher.getAuthTag();
  return Buffer.concat([encrypted, authTag]);
}

export function decryptChunk(encrypted: Buffer, nonce: Buffer, key: Buffer): Buffer {
  if (encrypted.length < AUTH_TAG_SIZE) {
    throw new Error("Encrypted chunk too short");
  }
  const authTag = encrypted.subarray(encrypted.length - AUTH_TAG_SIZE);
  const ciphertext = encrypted.subarray(0, encrypted.length - AUTH_TAG_SIZE);
  const decipher = crypto.createDecipheriv(ALGORITHM, key, nonce);
  decipher.setAuthTag(authTag);
  return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
}

export function extractNonceFromChunk(encryptedChunk: Buffer): Buffer {
  return encryptedChunk.subarray(0, NONCE_SIZE);
}

export function extractCiphertextAndTag(encryptedChunk: Buffer): { ciphertext: Buffer; authTag: Buffer } {
  const nonce = extractNonceFromChunk(encryptedChunk);
  const remaining = encryptedChunk.subarray(NONCE_SIZE);
  const authTag = remaining.subarray(remaining.length - AUTH_TAG_SIZE);
  const ciphertext = remaining.subarray(0, remaining.length - AUTH_TAG_SIZE);
  return { ciphertext, authTag };
}

export function createChunkEncryptor(key: Buffer, nonce: Buffer): (plaintext: Buffer) => Buffer {
  return (plaintext: Buffer) => encryptChunkWithNonce(plaintext, nonce, key);
}

export function createEncryptionStream(key: Buffer): Transform {
  let currentNonce: Buffer | null = null;
  return new Transform({
    transform(chunk, encoding, callback) {
      try {
        if (!currentNonce) {
          currentNonce = generateNonce();
        }
        const result = encryptChunkWithNonce(chunk, currentNonce, key);
        const fullChunk = Buffer.concat([currentNonce, result]);
        this.push(fullChunk);
        currentNonce = null;
        callback();
      } catch (err) {
        callback(err as Error);
      }
    },
  });
}

import crypto from "crypto";

const ALGORITHM = "aes-256-gcm";
const NONCE_SIZE = 12;
const AUTH_TAG_SIZE = 16;
const KEY_SIZE = 32;

export interface EncryptionKeyMaterial {
  key: Buffer;
  base64: string;
}

export interface EncryptionContext {
  nonce: Buffer;
  ivBase64: string;
}

export function generateEncryptionKey(): EncryptionKeyMaterial {
  const key = crypto.randomBytes(KEY_SIZE);
  return {
    key,
    base64: key.toString("base64"),
  };
}

export function generateNonce(): EncryptionContext {
  const nonce = crypto.randomBytes(NONCE_SIZE);
  return {
    nonce,
    ivBase64: nonce.toString("base64"),
  };
}

export function parseNonce(nonceBase64: string): Buffer {
  return Buffer.from(nonceBase64, "base64");
}

export function parseKey(keyBase64: string): Buffer {
  return Buffer.from(keyBase64, "base64");
}

export function encryptChunk(plaintext: Buffer, key: Buffer, nonce: Buffer): Buffer {
  const cipher = crypto.createCipheriv(ALGORITHM, key, nonce);
  const encrypted = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const authTag = cipher.getAuthTag();
  return Buffer.concat([nonce, encrypted, authTag]);
}

export function decryptChunk(encryptedChunk: Buffer, key: Buffer): Buffer {
  if (encryptedChunk.length < NONCE_SIZE + AUTH_TAG_SIZE) {
    throw new Error("Encrypted chunk too short");
  }

  const nonce = encryptedChunk.subarray(0, NONCE_SIZE);
  const authTag = encryptedChunk.subarray(encryptedChunk.length - AUTH_TAG_SIZE);
  const ciphertext = encryptedChunk.subarray(NONCE_SIZE, encryptedChunk.length - AUTH_TAG_SIZE);

  const decipher = crypto.createDecipheriv(ALGORITHM, key, nonce);
  decipher.setAuthTag(authTag);

  return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
}

export function extractNonceFromChunk(encryptedChunk: Buffer): Buffer {
  return encryptedChunk.subarray(0, NONCE_SIZE);
}

export function extractAuthTag(encryptedChunk: Buffer): Buffer {
  return encryptedChunk.subarray(encryptedChunk.length - AUTH_TAG_SIZE);
}

export function getEncryptedChunkSize(plaintextSize: number): number {
  return NONCE_SIZE + plaintextSize + AUTH_TAG_SIZE;
}

