      return NextResponse.json({ messageId, fileId: tgFileId, chunkIndex, hash: storedHash, nonce: chunkNonce, size: dataToStore.length });
    } catch (err: any) {
      lastError = err;
      if (err?.code === 429 && attempt < RETRY_DELAYS.length - 1) {
