    const children = await Folder.find({
      parent_id: { $in: frontier },
      deleted: { $ne: true },
    }).select("_id").lean();

    if (children.length === 0) break;

    const childIds = children.map((c) => c._id.toString());
    await Folder.updateMany(
      { _id: { $in: childIds } },
      { $set: { deleted: true, deletedAt } }
    );

    subtreeIds.push(...childIds);
    frontier = childIds;
