  await File.updateMany(
    {
      $or: [{ folderId: { $in: subtreeIds } }, { folders_id: { $in: subtreeIds } }],
      deleted: { $ne: true },
    },
    { $set: { deleted: true, deletedAt } }
  );

  return { folderCount: subtreeIds.length };
