  const [version] = await FileVersion.create(
    [
      {
        file_id: file._id,
        version: 1,
        backend: content.backend,
        storageUrl: content.storageUrl,
        hash: content.hash,
        size: content.size,
        mimetype: content.mimetype,
        createdBy,
      },
    ],
    { session }
  );

