    owner: { id: folder.owner_id, email: folder.owner_email },
    grants: grants.map((g) => ({
      id: g._id.toString(),
      principal: g.principalId,
      role: g.role,
      state: g.state,
      direct: String(g.folderId) === folderId,
      via: String(g.folderId),
