  const { reason } = await req.json().catch(() => ({}));

  await connectDB();

  const user = await (await import("@/adapters/database/models/User")).default.findOne({ email: authUser.email });
  if (!user) {
    return NextResponse.json({ error: "User not found" }, { status: 404 });
  }

