  if (!["pending", "uploading"].includes(file.status)) {
    return NextResponse.json({ error: `Cannot pause file in status "${file.status}"` }, { status: 409 });
  }

  file.status = "paused";
  await file.save();

  return NextResponse.json({ message: "Upload paused" });
