  // recovery-code login without needing the (deliberately unverifiable)
  // DEK-unwrap step to succeed first.
  doc.encryptionRecoveryCodeHash = await bcrypt.hash(recoveryCode, 10);
  doc.encryptionSetupAt = new Date();
