import { NextRequest, NextResponse, after } from "next/server";
import { getAuthUser } from "@/server/auth/auth";
import { getFileChunkData } from "@/server/services/fileService";
import { ServiceError } from "@/server/services/shareService";
import { getFile, getFileDownloadUrl } from "@/adapters/storage/telegram";
import { getCachedChunk, cacheChunkBestEffort } from "@/server/lib/telegramChunkCache";

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string; index: string }> },
) {
  try {
    const user = await getAuthUser();
    if (!user?.userId) return NextResponse.json({ error: "Unauthorised" }, { status: 401 });

    const { id, index } = await params;
    const versionId = req.nextUrl.searchParams.get("versionId");
    const chunkIndex = parseInt(index, 10);
    if (!versionId || isNaN(chunkIndex) || chunkIndex < 0) {
      return NextResponse.json({ error: "versionId and a valid chunk index are required" }, { status: 400 });
    }

    const chunk = await getFileChunkData(user.userId, id, versionId, chunkIndex);

    const cached = await getCachedChunk(versionId, chunkIndex);
    if (cached) {
      return new NextResponse(new Uint8Array(cached), {
        status: 200,
        headers: {
          "Content-Type": "application/octet-stream",
          "Content-Length": String(chunk.size),
          "Cache-Control": "private, max-age=86400, immutable",
        },
      });
    }

    const { filePath } = await getFile(chunk.telegramFileId);
    const tgRes = await fetch(getFileDownloadUrl(filePath));
    if (!tgRes.ok || !tgRes.body) {
      return NextResponse.json({ error: "Failed to fetch chunk from storage" }, { status: 502 });
    }

    const data = Buffer.from(await tgRes.arrayBuffer());
    after(() => cacheChunkBestEffort(versionId, chunkIndex, data));

    return new NextResponse(new Uint8Array(data), {
      status: 200,
      headers: {
        "Content-Type": "application/octet-stream",
        "Content-Length": String(chunk.size),
        // Ciphertext for a given (versionId, chunkIndex) is immutable.
        "Cache-Control": "private, max-age=86400, immutable",
      },
    });
  } catch (err) {
    if (err instanceof ServiceError) return NextResponse.json({ error: err.message }, { status: err.status });
    console.error("[GET /api/files/:id/chunk-data/:index]", err);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

import mongoose, { Schema, Document } from "mongoose";

export interface IFolder extends Document {
  name: string;
  owner_id: string;
  owner_email: string;
  parent_id?: string | null; // for nested folders
  // Materialized path: root -> ... -> immediate parent, NOT including self.
  // This is the backbone of the permission-inheritance model — permission
  // resolution reads this array instead of walking parent_id recursively,
  // and it is the only thing a folder move has to rewrite (never the
  // permission grants themselves). See permissionService.ts.
  ancestors: mongoose.Types.ObjectId[];
  depth: number;
  // Optimistic-concurrency token, hand-rolled (not mongoose's __v) so a
  // move's compare-and-swap filter can target it explicitly. Incremented on
  // every parent_id/ancestors change.
  opVersion: number;
  createdBy?: string | null;
  deleted: boolean;
  deletedAt: Date | null;
  createdAt: Date;
}

const FolderSchema = new Schema<IFolder>(
  {
    name:        { type: String, required: true },
    owner_id:    { type: String, required: true },
    owner_email: { type: String, required: true },
    parent_id:   { type: String, default: null },
    ancestors:   { type: [Schema.Types.ObjectId], default: [] },
    depth:       { type: Number, default: 0 },
    opVersion:   { type: Number, default: 0 },
    createdBy:   { type: String, default: null },
    deleted:     { type: Boolean, default: false },
    deletedAt:   { type: Date, default: null },
  },
  { timestamps: true }
);

FolderSchema.index({ owner_email: 1, createdAt: -1 });
FolderSchema.index({ owner_id: 1, parent_id: 1 });
FolderSchema.index({ owner_id: 1, deleted: 1 });
// Multikey index — powers "find every descendant of folder X" (used by
// moveFolder's subtree rewrite and cascade delete) in a single query
// instead of a level-by-level walk.
FolderSchema.index({ ancestors: 1 });

export default mongoose.models.Folder ||
  mongoose.model<IFolder>("Folder", FolderSchema);
