    if (d > winnerDepth) {
      winner = g;
      winnerDepth = d;
    }
  }
  if (!winner || winner.state === "revoked") return null;

  return {
    role: winner.role,
    source: String(winner.folderId) === folderId ? "direct" : "inherited",
    via: String(winner.folderId),
  };
}

