      // Whatever encryption mode the Telegram attempt was using no longer
      // applies once bytes land in S3 as plaintext, so this is reset
      // explicitly rather than left stale and misleading.
      encryptionMode: "none",
      encryptionKey: null,
      encryptionIv: null,
