  if (chunkCount !== file.totalChunks) {
    return NextResponse.json(
      { error: `Only ${chunkCount}/${file.totalChunks} chunks uploaded` },
      { status: 400 },
    );
  }

  if (file.status === "uploaded") {
    return NextResponse.json({ file, alreadyUploaded: true });
  }

