    console.warn(`[POST /api/files/${id}/fallback-to-s3] completed with cleanup warnings`, cleanupWarnings);
  }

  return NextResponse.json({
    fileId: id,
    backend: "s3",
    status: "s3_pending",
    key,
    cleanupWarnings: cleanupWarnings.length > 0 ? cleanupWarnings : undefined,
