    data: {
      fileId: existingFile._id.toString(),
      versionId: versionId?.toString() ?? null,
      storageUrl: version.storageUrl,
      keyBase64: encryptionKey?.keyBase64 ?? "",
      mimetype: version.mimetype,
      size: version.size,
    },
  };
