      userId: user.userId,
      email: user.email,
      provider: user.provider,
      storageused: user.storageused,
      storagelimit: user.storagelimit,
    },
    ACCESS_SECRET,
    { expiresIn: `${ACCESS_MAX_AGE_MINUTES}m` }
