    <AuthContext.Provider value={{ user, isReady, isAuthenticated: !!user, setAuthUser, logout }}>
      {children}
      {dekModal === 'setup' && user && (
        <EncryptionSetupModal userId={user.userId} onComplete={() => setDekModal(null)} />
      )}
    </AuthContext.Provider>
  );
