              content,
              createdBy: user._id,
              extraFileFields,
            });
      });

      return NextResponse.json(
        result!.versioned ? { file: result!.file, version: result!.version, versioned: true } : { file: result!.file },
        { status: 201 }
      );
    } finally {
      await session.endSession();
    }
  } catch (err) {
    console.error(err);
    return NextResponse.json({ error: "Server error" }, { status: 500 });
