      new CreateMultipartUploadCommand({
        Bucket: BUCKET,
        Key: key,
        ContentType: mimeType,
      })
    ));
  } catch (err) {
    console.error(`[POST /api/files/fallback-to-s3/init] S3 CreateMultipartUpload failed for file ${fileId} (key ${key})`, err);
