export async function GET(req: NextRequest) {
  try {
    const user = await getAuthUser();
    if (!user?.userId) return NextResponse.json({ error: "Unauthorised" }, { status: 401 });

    const { searchParams } = new URL(req.url);
    const parent_id = searchParams.get("parent_id");
    const sharedWithMe = searchParams.get("sharedWithMe") === "1";

    await connectDB();

    if (sharedWithMe) {
      const folders = await getFoldersSharedWithMe(user.userId);
      return NextResponse.json({ folders });
    }

    const folders = await Folder.find({ owner_id: user.userId, parent_id: parent_id || null, deleted: { $ne: true } }).lean();
    return NextResponse.json({ folders });
  } catch (err) {
    console.error("[GET /api/folders]", err);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

