    (async () => {
      try {
        const deviceKeyBase64 = await getDeviceDEK(user.userId);
        if (deviceKeyBase64) {
          const dek = await importDEK(base64ToBuffer(deviceKeyBase64));
          if (!cancelled) {
            setSessionDEK(dek);
            setDekBootstrappedFor(user.userId);
