  userId: string,
  hash: string,
  backend: "s3" | "telegram" = "s3"
) {
  await connectDB();

  const file = await File.findOne({
    hash,
    owner_id: userId,
    status: "uploaded",
    backend,
  }).lean();

  return file;
}

