    name: name.trim(),
    owner_id: String(parent.owner_id),
    owner_email: parent.owner_email,
    parent_id: parentId,
    ancestors: [...normalizedAncestors(parent), parent._id],
    depth: (parent.depth ?? 0) + 1,
