    return NextResponse.json({ error: "file id and storageUrl are required" }, { status: 400 });
  }

  await connectDB();

  const file = await File.findOne({ _id: id, owner_id: user.userId, status: "uploaded", deleted: { $ne: true } }).lean();
  if (!file) {
