    ? await Object.assign(file, fields).save({ session })
    : await File.findByIdAndUpdate(file._id, { $set: fields }, { session, new: true });

  await User.findByIdAndUpdate(
    updatedFile!.owner_id,
    { $inc: { storageused: content.size } },
